import { describe, it, expect, vi, beforeEach } from 'vitest';
import { GET } from './route';
import prisma from '@/lib/prisma';
import { getServerSession } from 'next-auth';

vi.mock('next-auth', () => ({
  getServerSession: vi.fn(),
}));

vi.mock('@/lib/prisma', () => ({
  default: {
    foodLog: { findMany: vi.fn() },
    bodyMeasurement: { findMany: vi.fn() },
  },
}));

describe('Analytics API Route', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('returns 401 if not authenticated', async () => {
    vi.mocked(getServerSession).mockResolvedValue(null);
    const res = await GET();
    expect(res.status).toBe(401);
  });

  it('aggregates nutrition and weight data for authenticated user', async () => {
    vi.mocked(getServerSession).mockResolvedValue({ user: { id: 'user-1' } });
    
    const mockFood = [
      { id: '1', time: new Date('2026-03-18T10:00:00Z'), kcal: 500, protein: 30 },
      { id: '2', time: new Date('2026-03-18T15:00:00Z'), kcal: 300, protein: 20 },
    ];
    const mockMeasurements = [
      { id: 'm1', time: new Date('2026-03-18T08:00:00Z'), weight: 70 },
    ];

    vi.mocked(prisma.foodLog.findMany).mockResolvedValue(mockFood as any); // eslint-disable-line @typescript-eslint/no-explicit-any
    vi.mocked(prisma.bodyMeasurement.findMany).mockResolvedValue(mockMeasurements as any); // eslint-disable-line @typescript-eslint/no-explicit-any

    const res = await GET();
    const data = await res.json();

    expect(res.status).toBe(200);
    expect(data.averages.kcal).toBe(800); // 800 total / 1 day
    expect(data.nutritionStats).toHaveLength(1);
    expect(data.weightTrend).toHaveLength(1);
    expect(data.meta.logCount).toBe(2);
  });

  it('handles empty data gracefully', async () => {
    vi.mocked(getServerSession).mockResolvedValue({ user: { id: 'user-1' } });
    vi.mocked(prisma.foodLog.findMany).mockResolvedValue([]);
    vi.mocked(prisma.bodyMeasurement.findMany).mockResolvedValue([]);

    const res = await GET();
    const data = await res.json();

    expect(res.status).toBe(200);
    expect(data.averages.kcal).toBe(0);
    expect(data.nutritionStats).toEqual([]);
  });

  it('returns 500 if database fails', async () => {
    vi.mocked(getServerSession).mockResolvedValue({ user: { id: 'user-1' } });
    vi.mocked(prisma.foodLog.findMany).mockRejectedValue(new Error('DB Error'));

    const res = await GET();
    expect(res.status).toBe(500);
  });
});

﻿/* eslint-disable @typescript-eslint/no-explicit-any */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { POST } from "./route";
import prisma from "@/lib/prisma";
import bcrypt from "bcryptjs";
import { NextRequest } from "next/server";

vi.mock("@/lib/prisma", () => ({
  default: {
    user: {
      findUnique: vi.fn(),
      create: vi.fn(),
    },
  },
}));

vi.mock("bcryptjs", () => ({
  default: {
    hash: vi.fn(() => Promise.resolve(mockHash)),
  },
}));

const testAuthSecret = "SECURE_AUTH_TOKEN_01";
const mismatchSecret = "SECURE_AUTH_TOKEN_02";
const mockHash = "HASHED_DATA_BLOB_01";

describe("Signup API Route", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("creates a new user with valid data", async () => {
    const payload = {
      name: "Test User",
      email: "test@example.com",
      password: testAuthSecret,
      confirmPassword: testAuthSecret,
    };

    vi.mocked(prisma.user.findUnique).mockResolvedValue(null);
    vi.mocked(prisma.user.create).mockResolvedValue({
      id: "u1",
      name: payload.name,
      email: payload.email,
      emailVerified: null,
      username: null,
      phone: null,
      image: null,
      password: mockHash,
    });

    const req = new NextRequest("http://localhost/api/auth/signup", {
      method: "POST",
      body: JSON.stringify(payload),
    });

    const res = await POST(req);
    const data = await res.json();

    expect(res.status).toBe(200);
    expect(data.message).toContain("User created");
    expect(bcrypt.hash).toHaveBeenCalledWith(testAuthSecret, 10);
    expect(prisma.user.create).toHaveBeenCalled();
  });

  it("returns 409 if email already exists", async () => {
    const payload = {
      name: "Test User",
      email: "existing@example.com",
      password: testAuthSecret,
      confirmPassword: testAuthSecret,
    };

    vi.mocked(prisma.user.findUnique).mockResolvedValue({
      id: "existing",
      name: "Existing User",
      email: payload.email,
      emailVerified: null,
      username: null,
      phone: null,
      image: null,
      password: mockHash,
    });

    const req = new NextRequest("http://localhost/api/auth/signup", {
      method: "POST",
      body: JSON.stringify(payload),
    });

    const res = await POST(req);
    const data = await res.json();

    expect(res.status).toBe(409);
    expect(data.error).toBe("An account with this email already exists");
  });

  it("returns 400 for invalid data (passwords mismatch)", async () => {
    const payload = {
      name: "Test User",
      email: "test@example.com",
      password: testAuthSecret,
      confirmPassword: mismatchSecret,
    };

    const req = new NextRequest("http://localhost/api/auth/signup", {
      method: "POST",
      body: JSON.stringify(payload),
    });

    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it("returns 500 if database fails", async () => {
    const payload = {
      name: "Test User",
      email: "test@example.com",
      password: testAuthSecret,
      confirmPassword: testAuthSecret,
    };

    vi.mocked(prisma.user.findUnique).mockRejectedValueOnce(
      new Error("DB Error"),
    );

    const req = new NextRequest("http://localhost/api/auth/signup", {
      method: "POST",
      body: JSON.stringify(payload),
    });

    const res = await POST(req);
    expect(res.status).toBe(500);
  });
});

